export default {
  file: "2026-0901-texts-tt.docx",
  date: "2026-09-01",
  key: "09-01",
  paragraphs: 338,
  blocks: [
    {"k": "heading", "p": [0, 0], "text": "SEPTEMBER 1"},
    {"k": "heading", "p": [1, 1], "text": "Church New Year (Indiction)"},
    {"k": "heading", "p": [2, 2], "text": "St. Simeon the Stylite (the Elder) and his mother, Ven. Martha"},
    {"k": "heading", "p": [4, 4], "text": "\"Lord I Call...\" Tone 1"},
    {"k": "text", "p": [6, 11], "text": "[Lord], I call upon Thee, [hear] me! | [Hear] me, O Lord! | [Lord], I call upon Thee, [hear] me! | Re[ceive] the [voice] of my prayer, | when I [call] up[on] Thee! // [Hear] [me], O Lord!", "n": 6, "head": "\"Lord I Call...\" Tone 1", "pointed": true},
    {"k": "text", "p": [13, 17], "text": "Let my [prayer] arise | in Thy sight as [in]cense, | and [let] the lifting [up] of my hands | be an [eve]ning [sac]rifice! // [Hear] [me], O Lord!", "n": 5, "head": "\"Lord I Call...\" Tone 1", "pointed": true},
    {"k": "text", "p": [19, 19], "text": "V. (10) Bring my soul out of prison, that I may give thanks to Thy Name.", "n": 1, "head": "\"Lord I Call...\" Tone 1"},
    {"k": "heading", "p": [21, 21], "text": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)"},
    {"k": "text", "p": [23, 28], "text": "Let us cry [out] every day to the Cre[a]tor | with the very words of [Christ] Himself! | He [taught] this prayer to His Dis[ci]ples: | “Our [Fa]ther in [heav]en, | give us this [day] our [dai]ly bread, // and overlook our [man]y sins!”", "n": 6, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)", "pointed": true},
    {"k": "text", "p": [30, 30], "text": "V. (9) The righteous will surround me, for Thou wilt deal bountifully with me.", "n": 1, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)"},
    {"k": "text", "p": [32, 36], "text": "He Who [wrote] the Law on Mount Sinai in [days] of old | came in the flesh to the town of [Naz]areth: | Christ our [God] took the scroll of the [Proph]et in His hands. | After He read, He closed it and began to [teach] the [peo]ple // that the Scriptures reach their ful[fill]ment in Him.", "n": 5, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)", "pointed": true},
    {"k": "text", "p": [38, 38], "text": "V. (8) Out of the depths I cry to Thee, O Lord. Lord, hear my voice!", "n": 1, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)"},
    {"k": "text", "p": [40, 44], "text": "As [once] in the [wil]derness, | those who did not truly obey Thee, the [Mas]ter of all, | were [scat]tered on the earth as it was [fit]ting, | so now too, O [Christ], as the [psalm] says: // “Scatter the bones of the impious and faithless at the mouth of [Ha]des!”", "n": 5, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)", "pointed": true},
    {"k": "text", "p": [46, 46], "text": "V. (7) Let Thine ears be attentive to the voice of my supplications!", "n": 1, "head": "Tone 1 (for the Indiction) (Joy of the Heavenly Hosts)"},
    {"k": "heading", "p": [48, 48], "text": "Tone 5 (for St. Simeon) (O venerable father)"},
    {"k": "text", "p": [50, 57], "text": "O [ven]erable [Fa]ther, | if it were possible for thy [pil]lar to speak, | it would [ev]er sing of thy pangs, thy labors and lamen[ta]tions. | For it did [not] merely [bear] thee; | it was itself borne, like a tree [wa]tered with thy tears. | The [an]gels were amazed, and men [mar]veled. | The [de]mons feared thy [pa]tience. // O venerable Simeon, [pray] that our [souls] may be saved!", "n": 8, "head": "Tone 5 (for St. Simeon) (O venerable father)", "pointed": true},
    {"k": "text", "p": [59, 59], "text": "V. (6) If Thou, O Lord, shouldst mark iniquities, Lord, who could stand? But there is forgiveness with Thee.", "n": 1, "head": "Tone 5 (for St. Simeon) (O venerable father)"},
    {"k": "text", "p": [61, 68], "text": "O [ven]erable [Fa]ther, | emulating thy Master through the power of the divine [Spir]it, | thou didst [mount] thy pillar as [though] it were a cross. | He rent a[sun]der the handwriting of the [sins] of all, | and thou didst put down the uprisings of the [pas]sions. | [He] was like a lamb; thou like a [sac]rifice. | He as[cend]ed the Cross; thou the [pil]lar. // O venerable Simeon, [pray] that our [souls] may be saved!", "n": 8, "head": "Tone 5 (for St. Simeon) (O venerable father)", "pointed": true},
    {"k": "text", "p": [70, 70], "text": "V. (5) For Thy Name’s sake I wait for Thee, O Lord. My soul has waited for Thy word; my soul has hoped on the Lord.", "n": 1, "head": "Tone 5 (for St. Simeon) (O venerable father)"},
    {"k": "text", "p": [73, 81], "text": "O [ven]erable [Fa]ther, | having drenched thy body with tears and [cleansed] thy soul, | thou didst as[cend] to the heights of [vir]tues; | [there]fore, by having thy pillar as a visible [dwell]ing, | while the heavenly city, Mount Zion, was thy [spir]itual abode, | thou didst a[maze] the [an]gels. | Thou didst as[ton]ish men and put [de]mons to shame | by thy [vir]tuous deeds. // O venerable Simeon, [pray] for the sal[va]tion of our souls!", "n": 9, "head": "Tone 5 (for St. Simeon) (O venerable father)", "pointed": true},
    {"k": "text", "p": [83, 83], "text": "V. (4) From the morning watch until night, from the morning watch, let Israel hope on the Lord!", "n": 1, "head": "Tone 5 (for St. Simeon) (O venerable father)"},
    {"k": "heading", "p": [85, 85], "text": "Tone 2 Idiomela (for St. Simeon)"},
    {"k": "text", "p": [87, 92], "text": "A good fruit sprouted from a [good] root, — | the holy Simeon, nourished from infancy by [grace] rather than milk; | and [el]evating his body upon a rock while exalting his [mind] towards God, | he constructed with virtues an a[bode] in the air, | and walking on high with the divine [Pow]ers, // he became a dwelling-place of Christ, the God and the [Sav]ior of our souls.", "n": 6, "head": "Tone 2 Idiomela (for St. Simeon)", "pointed": true},
    {"k": "text", "p": [94, 94], "text": "V. (3) For with the Lord there is mercy and with Him is plenteous redemption, and He will deliver Israel from all his iniquities.", "n": 1, "head": "Tone 2 Idiomela (for St. Simeon)"},
    {"k": "text", "p": [96, 101], "text": "O venerable Father Simeon, blessed [ser]vant, | the remembrance of thee and the meekness of thy heart continues for[ev]er; | though [thou], the good shepherd, hast de[part]ed from us, | yet thou hast not withdrawn from us in [spir]it. | As thou standest before God in love, rejoicing with the angels in [heav]en, // with them intercede that our [souls] may be saved!", "n": 6, "head": "Tone 2 Idiomela (for St. Simeon)", "pointed": true},
    {"k": "text", "p": [103, 103], "text": "V. (2) Praise the Lord, all nations! Praise Him, all peoples!", "n": 1, "head": "Tone 2 Idiomela (for St. Simeon)"},
    {"k": "note", "p": [105, 105], "text": "(by Cyprian)"},
    {"k": "text", "p": [107, 113], "text": "The casket of thy relics, O all-praised [Fa]ther, | is a source of [heal]ings; | and thy holy [soul], united with the angels, is worthily [glor]ified. | Therefore having boldness to ap[proach] the Lord, | and dancing with the bodiless hosts in heaven, O venerable [Sim]eon, // entreat Him that our [souls] may be saved! | V. (1) For His mercy is confirmed on us, and the truth of the Lord endures forever.", "n": 7, "head": "Tone 2 Idiomela (for St. Simeon)", "pointed": true},
    {"k": "note", "p": [115, 115], "text": "(by Germanos)"},
    {"k": "text", "p": [117, 123], "text": "Thou didst love the highest philosophy, O [God]-bearer, | dwelling outside the world, and living above [vis]ible things; | and thou wast re[vealed] as a most divine, untarnished [mir]ror of God. | Being ever [joined] to the Light, | thou wast a re[ceiv]er of the light, | and [clear]ly attained the [bless]ed end. // Intercede for our souls, O wise [Sim]eon!", "n": 7, "head": "Tone 2 Idiomela (for St. Simeon)", "pointed": true},
    {"k": "note", "p": [125, 125], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "heading", "p": [127, 127], "text": "Tone 6 (for St. Simeon, by Germanos)"},
    {"k": "text", "p": [129, 132], "text": "Grace overshadows the casket of thy relics, O sanctified [Sim]eon; | therefore we run to the fragrance of thy [mir]acles, | drawing for ourselves the healing of [sick]nesses. // Intercede with Christ God on be[half] of our souls!", "n": 4, "head": "Tone 6 (for St. Simeon, by Germanos)", "pointed": true},
    {"k": "note", "p": [134, 134], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [136, 136], "text": "Tone 6 (for the Indiction, by Byzantius)"},
    {"k": "text", "p": [138, 143], "text": "O timeless Word and Son without be[gin]ning, | united with the Holy [Spir]it, | Co-maker of all and Co-creator of all things visible and in[vis]ible: | bless the be[gin]ning of this year; | and bring peace to Thine Orthodox [peo]ple, // through the prayers of the Theotokos and [all] the saints!", "n": 6, "head": "Tone 6 (for the Indiction, by Byzantius)", "pointed": true},
    {"k": "heading", "p": [145, 145], "text": "Old Testament Readings"},
    {"k": "heading", "p": [146, 146], "text": "Isaiah 61:1-9 (Indiction)"},
    {"k": "heading", "p": [147, 147], "text": "Composite 24 (Leviticus 26:3-12, 14-17, 19-20, 22, 33, 23-24) (Indiction)"},
    {"k": "heading", "p": [148, 148], "text": "Wisdom of Solomon 4:7-15 (St. Simeon)"},
    {"k": "heading", "p": [149, 149], "text": "Aposticha"},
    {"k": "heading", "p": [151, 151], "text": "Tone 1 Idiomela (for the Indiction, by John the Monk)"},
    {"k": "text", "p": [153, 162], "text": "The [en]trance of the [year] is at hand, | summoning together the distinguished saints to [hon]or it: | Cal[li]sta, Evódius, and Hermógenes, brethren and [cham]pions; | Simeon, the [e]qual of the [an]gels; | [Josh]ua, the [son] of Nun; | the Seven Youths of [Eph]esus; | and the [choir] of the forty holy women, forty times [ra]diant. | As we celebrate their memory, let us cry [out], O [lov]ers of feasts: | “O [Lord], bless the [work] of Thy hands, // and make us worthy to pass profitably through the [course] of the year!”", "n": 10, "head": "Tone 1 Idiomela (for the Indiction, by John the Monk)", "pointed": true},
    {"k": "text", "p": [164, 164], "text": "V. Praise is due to Thee, O God, in Zion, and to Thee shall vows be performed.", "n": 1, "head": "Tone 1 Idiomela (for the Indiction, by John the Monk)"},
    {"k": "note", "p": [165, 165], "text": "(Ps. 64:1)"},
    {"k": "text", "p": [167, 172], "text": "O [Christ] our God, Who in wisdom didst [fash]ion all things, | and out of nothing hast brought them into [be]ing, | bless the [crown] of the year, and preserve our [cit]y unharmed; | and make our faithful [glad] by Thy [pow]er, | granting them [vic]tories over their [ad]versaries, // through the Theotokos bestowing upon the world great [mer]cy!", "n": 6, "head": "Tone 1 Idiomela (for the Indiction, by John the Monk)", "pointed": true},
    {"k": "text", "p": [174, 174], "text": "V. We shall be filled with the good things of Thy house; holy is Thy temple, wonderful in righteousness. (Ps. 64:5)", "n": 1, "head": "Tone 1 Idiomela (for the Indiction, by John the Monk)"},
    {"k": "heading", "p": [176, 176], "text": "Tone 2 (by Cyprian)"},
    {"k": "text", "p": [178, 189], "text": "Thou art wonderful, O God, and [won]drous are Thy works! | All Thy ways are un[search]able! | For [Thou] art the Wisdom and perfect Hypostasis and [Pow]er of God; | Thy working together is co-unoriginate and co-e[ter]nal; | therefore, by Thine al[migh]ty pow’r, | Thou didst [come] into the world, seeking to beautify Thy [crea]ture, | in an inexpressible manner—from a Mother who had [not] known man, | yet, not changing in Thy [God]head; | for Thou hast [planned] the seasons and the ages to accomplish our salvation, O [Change]less One. | Therefore we cry [out] to Thee: // “O Good Lord, [glo]ry to Thee!” | V. Bless the crown of the year with Thy goodness, O Lord! (Ps. 64:12a)", "n": 12, "head": "Tone 2 (by Cyprian)", "pointed": true},
    {"k": "note", "p": [191, 191], "text": "(by St. John of Damascus)"},
    {"k": "text", "p": [193, 198], "text": "O pre-eternal Word of the [Fa]ther, | Who in wisdom didst [fash]ion all things, | and didst es[tab]lish the whole creation by Thine all-[pow]erful word, | bless the crown of the year with Thy [good]ness, | and overthrow heresies, through the Theo[to]kos, // for Thou art good and the [Lov]er of man!", "n": 6, "head": "Tone 2 (by Cyprian)", "pointed": true},
    {"k": "note", "p": [200, 200], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "heading", "p": [202, 202], "text": "Tone 5 (for St. Simeon)"},
    {"k": "text", "p": [204, 210], "text": "As E[lij]ah found a chariot of fire to as[cend] the heights, | so didst thou devise a good [lad]der | by [which] thou didst go [up] on high. | Al[though] he did not leave behind for others his [way] of ascent, | thou, even after death, hast kept thy [pil]lar. | O heavenly [man], angel on earth, unsleeping beacon of the in[hab]ited world, // O venerable Simeon, inter[cede] for the sal[va]tion of our souls!", "n": 7, "head": "Tone 5 (for St. Simeon)", "pointed": true},
    {"k": "note", "p": [212, 212], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [214, 214], "text": "Tone 5 (for the Indiction, by John the Monk)"},
    {"k": "text", "p": [216, 225], "text": "O [King], Who remainest for[ev]er | and art everlasting unto the [a]ges, | do [Thou] accept the supplication of sinners asking sal[va]tion, | and [grant] a[bun]dance to Thine earth, | bestowing temperate weather, O [Lov]er of man! | Be the [al]ly of the faithful Orthodox in battles against the ungodly bar[bar]ians, | as [once] Thou wast unto [Da]vid; | for they have come into Thy tabernacles and defiled Thine all-holy place, O [Sav]ior! | Grant [vic]tories, O Christ God, by the intercession of the Theo[to]kos, // for Thou art the victory and [boast] of the [Or]thodox!", "n": 10, "head": "Tone 5 (for the Indiction, by John the Monk)", "pointed": true},
    {"k": "heading", "p": [228, 228], "text": "(at Vespers)"},
    {"k": "heading", "p": [230, 230], "text": "Tone 2 Troparion (Indiction)"},
    {"k": "text", "p": [232, 236], "text": "O Cre[a]tor of the [U]niverse, | Thou didst appoint times by Thine own [pow]er; | [bless] the crown of this year with Thy [good]ness, O Lord! | Preserve in safety Thy rulers and Thy [cit]ies: // and through the intercessions of the Theo[to]kos, [save] us!", "n": 5, "head": "Tone 2 Troparion (Indiction)", "pointed": true},
    {"k": "note", "p": [238, 238], "text": "Glory to the Father, and to the Son, and to the Holy Spirit,"},
    {"k": "heading", "p": [240, 240], "text": "Tone 1 Troparion (St. Simeon)"},
    {"k": "text", "p": [242, 246], "text": "Thou wast a [pil]lar of patient en[dur]ance, | having imitated the Forefathers, O ^[Ven]erable One: | Job in suffering and Joseph in temp[ta]tions. | Thou didst [live] like the bodiless ones while yet in the flesh, O Simeon, our [Fa]ther. // Beseech Christ God that our [souls] may be saved!", "n": 5, "head": "Tone 1 Troparion (St. Simeon)", "pointed": true},
    {"k": "note", "p": [248, 248], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [250, 250], "text": "Tone 1 Troparion (Theotokos)"},
    {"k": "text", "p": [252, 256], "text": "Re[joice], O Virgin Theotokos, [full] of grace, | haven and protection of the [hu]man race; | for from [thee] the Redeemer of the world became in[car]nate; | for thou alone art Mother and Virgin, ever blessed and ^[glo]rified. // Intercede with Christ God that peace be granted to all the in[hab]ited earth!", "n": 5, "head": "Tone 1 Troparion (Theotokos)", "pointed": true},
    {"k": "heading", "p": [259, 259], "text": "(at the Divine Liturgy)"},
    {"k": "heading", "p": [261, 261], "text": "Tone 2 Troparion (Indiction)"},
    {"k": "text", "p": [263, 267], "text": "O Cre[a]tor of the [U]niverse, | Thou didst appoint times by Thine own [pow]er; | [bless] the crown of this year with Thy [good]ness, O Lord! | Preserve in safety Thy rulers and Thy [cit]ies: // and through the intercessions of the Theo[to]kos, [save] us!", "n": 5, "head": "Tone 2 Troparion (Indiction)", "pointed": true},
    {"k": "heading", "p": [269, 269], "text": "Tone 1 Troparion (Theotokos)"},
    {"k": "text", "p": [271, 275], "text": "Re[joice], O Virgin Theotokos, [full] of grace, | haven and protection of the [hu]man race; | for from [thee] the Redeemer of the world became in[car]nate; | for thou alone art Mother and Virgin, ever blessed and ^[glo]rified. // Intercede with Christ God that peace be granted to all the in[hab]ited earth!", "n": 5, "head": "Tone 1 Troparion (Theotokos)", "pointed": true},
    {"k": "heading", "p": [277, 277], "text": "Tone 1 Troparion (St. Simeon)"},
    {"k": "text", "p": [279, 283], "text": "Thou wast a [pil]lar of patient en[dur]ance, | having imitated the Forefathers, O ^[Ven]erable One: | Job in suffering and Joseph in temp[ta]tions. | Thou didst [live] like the bodiless ones while yet in the flesh, O Simeon, our [Fa]ther. // Beseech Christ God that our [souls] may be saved!", "n": 5, "head": "Tone 1 Troparion (St. Simeon)", "pointed": true},
    {"k": "heading", "p": [285, 285], "text": "Tone 2 Kontakion (St. Simeon)"},
    {"k": "text", "p": [287, 290], "text": "[Seek]ing the things of the [High]est, | and having made a fiery chariot, thou wast [joined] to the heights. | [There]fore, thou hast become a companion to the angels, O venerable [Sim]eon, // and with them thou art praying incessantly to [Christ] [God] for us all.", "n": 4, "head": "Tone 2 Kontakion (St. Simeon)", "pointed": true},
    {"k": "heading", "p": [292, 292], "text": "Tone 4 Kontakion (Indiction)"},
    {"k": "text", "p": [294, 298], "text": "O Creator and Master of time and the [a]ges, | Triune and Merciful [God] of all: | grant blessings for the [course] of this year, | and in Thy boundless mercy save those who worship Thee and cry [out] in fear: // “O Savior, grant blessings to [all] mankind!”", "n": 5, "head": "Tone 4 Kontakion (Indiction)", "pointed": true},
    {"k": "heading", "p": [299, 299], "text": "Tone 3 Prokeimenon (Indiction)"},
    {"k": "text", "p": [301, 302], "text": "Great is our Lord, and abundant in power, / His understanding is beyond | measure. (Ps. 146:5)", "n": 2, "head": "Tone 3 Prokeimenon (Indiction)"},
    {"k": "text", "p": [304, 304], "text": "V. Praise the Lord! For it is good to sing praises to our God! (Ps. 146:1)", "n": 1, "head": "Tone 3 Prokeimenon (Indiction)"},
    {"k": "heading", "p": [306, 306], "text": "Tone 7 Prokeimenon (St. Simeon)"},
    {"k": "text", "p": [308, 308], "text": "Precious in the sight of the Lord / is the death of His saints. (Ps. 115:6)", "n": 1, "head": "Tone 7 Prokeimenon (St. Simeon)"},
    {"k": "heading", "p": [310, 310], "text": "Epistle"},
    {"k": "text", "p": [311, 312], "text": "(282) 1 Timothy 2:1-7 (Indiction) | (258) Colossians 3:12-16 (St. Simeon)", "n": 2, "head": "Epistle"},
    {"k": "heading", "p": [314, 314], "text": "Tone 4"},
    {"k": "text", "p": [315, 315], "text": "Alleluia, Alleluia, Alleluia!", "n": 1, "head": "Tone 4"},
    {"k": "text", "p": [317, 317], "text": "V. Praise is due to Thee, O God, in Zion, and to Thee shall vows be performed.", "n": 1, "head": "Tone 4"},
    {"k": "note", "p": [318, 318], "text": "(Ps. 64:1)"},
    {"k": "text", "p": [320, 320], "text": "V. Bless the crown of the year with Thy goodness, O Lord! (Ps. 64:12a)", "n": 1, "head": "Tone 4"},
    {"k": "heading", "p": [321, 321], "text": "Tone 4"},
    {"k": "text", "p": [322, 322], "text": "V. Blessed is the man who fears the Lord, who greatly delights in His commandments. (Ps. 111:1)", "n": 1, "head": "Tone 4"},
    {"k": "heading", "p": [324, 324], "text": "Gospel"},
    {"k": "text", "p": [325, 326], "text": "(13) Luke 4:16-22 (Indiction) | (43) Matthew 11:27-30 (St. Simeon)", "n": 2, "head": "Gospel"},
    {"k": "heading", "p": [328, 328], "text": "Communion Hymn"},
    {"k": "text", "p": [330, 333], "text": "Thou shalt bless the crown of the year with Thy goodness, O Lord! (Ps. 64:12a) | The righteous shall be in everlasting remembrance! He shall not fear evil | tidings! (Ps. 111:6) | Alleluia, Alleluia, Alleluia!", "n": 4, "head": "Communion Hymn"},
    {"k": "note", "p": [336, 336], "text": "Prepared by the Department of Liturgical Music and Translations, Orthodox Church in America."},
  ],
};
